-- Dansk portion 1 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3332-6560.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish1'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish1', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3332,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken forstavelse mangler: 'Jeg kom til at ___forstå opgaven, så jeg lavede noget helt andet.'","o":["van","op","an","mis"],"a":"mis","r":"Forstavelsen mis- betyder, at noget går galt. At misforstå er at forstå noget forkert."},
{"l":3352,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Morfar sad altid på den samme bænk ved havnen. Efter at han var død, tog Elias derhen om søndagen. Han sagde ikke noget, men kiggede på bådene, ligesom morfar havde gjort. Nogle gange kunne han næsten høre ham nynne.' Hvorfor går Elias hen til bænken?","o":["Han vil føle sig tæt på sin morfar","Han vil lære at sejle en af bådene","Han venter på, at der kommer en båd","Han har aftalt at mødes med en ven der"],"a":"Han vil føle sig tæt på sin morfar","r":"Elias gør det samme som morfar og kan næsten høre ham. Bænken er en måde at huske ham på."},
{"l":3370,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kasper syntes, at det var uretfærdigt, at han skulle rydde op, når lillesøster havde lavet rodet. Han sagde det til far. Far nikkede og fandt en lille kost til lillesøsteren. Nu ryddede de op sammen, og hun syntes, det var en leg.' Hvordan løser far problemet?","o":["Han rydder selv op for begge børn","Han får begge børn til at rydde op sammen","Han sender Kasper op på sit værelse","Han siger, at Kasper skal lade rodet ligge"],"a":"Han får begge børn til at rydde op sammen","r":"Far er enig i problemet og giver lillesøster en kost, så de deler arbejdet."},
{"l":3392,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad råder ordsproget 'Man skal ikke kigge en given hest i munden' dig til?","o":["Du skal ikke købe en hest uden at prøve den","Du skal passe på, at dyr ikke bider dig","Du skal ikke kritisere en gave, du får","Du skal altid takke for maden efter måltidet"],"a":"Du skal ikke kritisere en gave, du får","r":"Ved hestehandel så man på tænderne for at finde hestens alder. Får man hesten forærende, er det uhøfligt at undersøge den."},
{"l":3410,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige flertalsform: 'De ___ huse i byen skal bevares.'","o":["gammle","gammele","gamele","gamle"],"a":"gamle","r":"Grundformen har dobbelt m, men i flertal falder e'et væk, og så står der kun ét m foran l."},
{"l":3432,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Alle vinduerne stod ___ i varmen.'","o":["åbne","åbene","åbenne","obne"],"a":"åbne","r":"Grundformen slutter på -en, men i flertal forsvinder e'et, så der står -bne."},
{"l":3454,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Da brandalarmen lød gik alle stille ud på parkeringspladsen.'?","o":["brandalarmen","lød","gik","alle"],"a":"lød","r":"'Da brandalarmen lød' er ledsætningen. Hovedsætningen begynder med 'gik', og kommaet skiller de to."},
{"l":3473,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har kommaet rigtigt, når Jonas fortæller om sin hund?","o":["Selvom hunden var, lille kunne den løbe hurtigt.","Selvom hunden var lille kunne, den løbe hurtigt.","Selvom hunden var lille, kunne den løbe hurtigt.","Selvom hunden var lille kunne den løbe hurtigt."],"a":"Selvom hunden var lille, kunne den løbe hurtigt.","r":"Ledsætningen 'Selvom hunden var lille' slutter efter 'lille'. Kommaet står mellem den og hovedsætningen."},
{"l":3492,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Kun ét af ordene Moster, Holland, Pandekager og Maj skal have stort bogstav i: 'Min Moster fra Holland spiser Pandekager i Maj.' Hvilket?","o":["Moster","Pandekager","Maj","Holland"],"a":"Holland","r":"Holland er et stednavn og skal have stort bogstav. Almindelige navneord som moster og pandekager og måneder som maj skrives med lille."},
{"l":3511,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Kun én af sætningerne om tasken er et direkte spørgsmål. Hvilken?","o":["Hvor har du lagt din taske","Hun spurgte, hvor tasken var","Jeg ved ikke, hvor tasken er","Han ville vide, hvor tasken lå"],"a":"Hvor har du lagt din taske","r":"Kun den sætning stiller selv spørgsmålet og skal slutte med spørgsmålstegn. De andre fortæller om et spørgsmål og får punktum."},
{"l":3531,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Jakken tilhører Viktor. Hvilket ord passer: 'Alfred har lånt ___ jakke.'","o":["sin","hans","sit","hendes"],"a":"hans","r":"'Sin' ville betyde, at jakken var Alfreds egen. Den er Viktors, så der skal stå 'hans'."},
{"l":3550,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'grundvand'?","o":["regnvand, der bliver samlet i en tønde","vand i den lave ende af en svømmehal","vand, der ligger dybt nede i jorden","havvand, der skyller op på stranden"],"a":"vand, der ligger dybt nede i jorden","r":"Regnvand siver ned gennem jorden og samler sig dybt nede som grundvand. Det meste af Danmarks drikkevand er grundvand."},
{"l":3572,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man det system, der fra hjertet bringer ilt og næring rundt i kroppen og tilbage igen?","o":["fordøjelsen","åndedrættet","nervesystemet","blodkredsløbet"],"a":"blodkredsløbet","r":"Blodet løber i et kredsløb og kommer tilbage til hjertet. Undervejs afleverer det ilt og næring."},
{"l":3587,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om svømmehallen har ingen overflødige kommaer?","o":["I går var vi i svømmehallen med klassen.","I går, var vi i svømmehallen med klassen.","I går var vi, i svømmehallen med klassen.","I går var, vi i svømmehallen med klassen."],"a":"I går var vi i svømmehallen med klassen.","r":"'I går' er et tidsled og ikke en ledsætning. Derfor skal der ikke være komma, selv om det står først."},
{"l":3608,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at male': 'I forgårs ___ vi hele køkkenet.'","o":["malet","malede","maler","male"],"a":"malede","r":"Der står ikke 'har' foran, så det er datid, og den ender på -ede. 'Malet' kræver 'har': Vi har malet."},
{"l":3630,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find det påpegende stedord: 'Disse sko er for små til mig.'","o":["sko","små","Disse","mig"],"a":"Disse","r":"'Disse' peger på bestemte sko. 'Mig' er også et stedord, men det er personligt, ikke påpegende."},
{"l":3648,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Marie fortalte alle, at hun skulle til Paris i ferien. Hun beskrev Eiffeltårnet og hotellet med swimmingpool. Da skolen begyndte igen, spurgte Sofie, om hun havde billeder. Marie blev rød i ansigtet og sagde, at hendes mobil var gået i stykker. På hendes taske hang stadig mærket fra sommerhuset i Blokhus.' Hvad antyder teksten?","o":["Maries mobil er blevet stjålet i Paris","Marie har glemt billederne på hotellet","Sofie har selv været i Paris med Marie","Marie har nok ikke været i Paris"],"a":"Marie har nok ikke været i Paris","r":"Den røde kind, undskyldningen og mærket fra Blokhus er spor, der peger på, at turen ikke er sket."},
{"l":3666,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sundby Skole får nye toiletter. I en undersøgelse sagde 7 ud af 10 elever, at de undgik skolens toiletter, fordi de var beskidte. Nu går skolen i gang med at renovere dem. Elevrådet skal være med til at vælge farverne.' Hvad fik skolen til at gå i gang?","o":["Elevernes svar i en undersøgelse","Elevrådet ønskede nye farver på gangene","Toiletterne var for små til alle eleverne","Elevrådet bad om nye toiletter"],"a":"Elevernes svar i en undersøgelse","r":"Undersøgelsen viste problemet, og derefter gik skolen i gang. Farvevalget kom først bagefter."},
{"l":3685,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at flyve' passer: 'Vi har ___ til Island to gange.'","o":["fløj","fløjet","flyver","flyve"],"a":"fløjet","r":"Efter 'har' står tillægsformen 'fløjet'. 'Fløj' er datid."},
{"l":3707,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mangler: 'Det er bare en ___, at alle katte hader vand. Du kan ikke bevise det.'","o":["kendsgerning","opskrift","påstand","undskyldning"],"a":"påstand","r":"En påstand er noget, man siger er sandt, uden at det er bevist. En kendsgerning er derimod bevist."},
{"l":3729,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led er 'Ella' i sætningen: 'Morfar gav Ella en hammer.'","o":["genstandsled","grundled","forholdsordsled","hensynsled"],"a":"hensynsled","r":"Ella er den, der modtager hammeren. Modtageren er hensynsled, mens 'en hammer' er genstandsled."},
{"l":3751,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er genstandsleddet: 'Moster lånte Mikkel sin telefon.'","o":["sin telefon","Mikkel","Moster","lånte"],"a":"sin telefon","r":"Spørg: Hvad lånte moster ud? 'Sin telefon' er genstandsleddet, og 'Mikkel' er hensynsleddet."},
{"l":3767,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes den modstand, der opstår, når to ting gnider mod hinanden?","o":["tyngdekraft","friktion","magnetisme","fordampning"],"a":"friktion","r":"Friktion er grunden til, at dine sko ikke glider på gulvet, og at hænderne bliver varme, når du gnider dem."},
{"l":3790,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvor i en fagbog slår du op for at finde den side, hvor et bestemt ord står?","o":["indholdsfortegnelse","forord","stikordsregister","kildeliste"],"a":"stikordsregister","r":"Et stikordsregister står bagest i bogen. Her kan du se, på hvilke sider et bestemt ord bliver brugt, mens indholdsfortegnelsen kun viser kapitlerne."},
{"l":3806,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Rosa har ondt i ___ finger.'","o":["hendes","sit","sine","sin"],"a":"sin","r":"Fingeren er Rosas egen, og det hedder en finger. Derfor skal der stå 'sin'."},
{"l":3827,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Danmark ejede engang øer i Caribien, kaldet Dansk Vestindien. Hvad kaldes et område, som et fjernt land styrer på den måde?","o":["en koloni","en kommune","en alliance","en fæstning"],"a":"en koloni","r":"En koloni er et område, der styres af et andet land langt væk. Dansk Vestindien blev solgt til USA i 1917."},
{"l":3850,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'tronfølger'?","o":["den, der vogter slottet, når kongen er ude at rejse","den, der skal overtage kongens eller dronningens plads","den, der bærer kronen hen til kongen under festen","den, der laver kongens og dronningens stole af træ"],"a":"den, der skal overtage kongens eller dronningens plads","r":"Tronen er kongens stol og et tegn på magten. Tronfølgeren sætter sig på tronen, når kongen eller dronningen stopper."},
{"l":3865,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"To venner vil se hver sin film, så de vælger en tredje, som de begge kan lide. Hvad kaldes sådan en løsning?","o":["et skænderi","et løfte","et kompromis","et forbud"],"a":"et kompromis","r":"Ved et kompromis giver begge parter sig lidt for at kunne blive enige."},
{"l":3887,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det sige at være 'hensynsfuld' over for andre?","o":["Man giver altid andre skylden for det hele","Man holder sig helst langt væk fra dem","Man tør altid sige dem imod ved møder","Man tænker på, hvordan de andre har det"],"a":"Man tænker på, hvordan de andre har det","r":"Hensynsfuld betyder, at man tænker på andre, f.eks. ved at være stille, når nogen sover."},
{"l":3905,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Har du ___ dine snørebånd?'","o":["bundet","bunnet","bindet","bindt"],"a":"bundet","r":"Ordet 'binde' skifter til u efter 'har'. D'et skal skrives, selvom man kun hører n."},
{"l":3925,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alle elever på Skovgårdsskolen har i september cyklet til skole, hvis de kunne. I alt blev det til 41.000 kilometer. Skolen vandt dermed den lokale cykelkonkurrence. Præmien på 5.000 kroner skal bruges på nye bolde. Skolelederen siger, at hun er meget stolt.' Hvad er hovedsagen i denne nyhed?","o":["At skolelederen er meget stolt af sine elever","At skolen vandt den lokale cykelkonkurrence","At der er for få bolde på skolens boldbane","At alle elever bor tæt på deres skole"],"a":"At skolen vandt den lokale cykelkonkurrence","r":"Det vigtigste er sejren. Stoltheden og boldene er detaljer, der hører til nyheden."},
{"l":3943,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Det er ikke altid dyrt at spise sundt. Gulerødder, havregryn og linser koster ikke meget. En gryde linsesuppe kan give mad til fire personer for nogle få kroner pr. person. Alligevel køber mange færdigretter, fordi de tror, de sparer tid.' Hvilken holdning har forfatteren nok til færdigretter?","o":["Forfatteren synes, at de er billige og nemme at købe i butikken","Forfatteren synes, at de er sundere end linser","Forfatteren tror ikke på, at de sparer så meget tid","Forfatteren mener, at de bør forbydes ved lov"],"a":"Forfatteren tror ikke på, at de sparer så meget tid","r":"Ordene 'alligevel' og 'tror' viser, at forfatteren ikke er enig med dem, der køber færdigretter. Der står intet om forbud."},
{"l":3962,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ida gjorde fortællingen om sin ferie meget vildere, end den havde været. Hvilken vending passer?","o":["Hun gik stille med dørene","Hun holdt sig på måtten","Hun gav op på forhånd","Hun smurte tykt på"],"a":"Hun smurte tykt på","r":"Ligesom man kan smøre for meget smør på brødet, kan man lægge for meget til en historie. At smøre tykt på er at overdrive."},
{"l":3985,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'geo-' i 'geografi' og 'geologi'?","o":["jord","liv","lys","vand"],"a":"jord","r":"Geo kommer fra græsk og betyder jord. Geografi handler om Jorden og landene, og geologi handler om jordens lag og sten."},
{"l":4005,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Filmen om den lille drage varer to timer, men den føles som fire. Historien er forudsigelig, og vittighederne er de samme som i den første film. Kun tegningerne af bjergene er flotte. Jeg gav op efter en time og begyndte at tælle lamperne i biografen.' Hvilken type tekst er det, og hvad mener skribenten?","o":["En reklame, hvor skribenten anbefaler filmen","En anmeldelse, hvor skribenten ikke kan lide filmen","En nyhed, hvor skribenten fortæller om optagelserne","En fortælling, hvor en drage rejser over bjergene"],"a":"En anmeldelse, hvor skribenten ikke kan lide filmen","r":"Skribenten vurderer filmen og finder næsten kun fejl. Det at tælle lamper viser, hvor kedeligt det var."},
{"l":4026,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad mangler? 'Kan du hjælpe mig med at ___ min cykel?'","o":["reparerer","reperere","reparere","repareret"],"a":"reparere","r":"Efter 'at' står navnemåden, som ender på -ere. Første vokal efter p er et a."},
{"l":4045,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad vil eventyret 'Nattergalen' især fortælle?","o":["Det dyreste er også det bedste i verden","Det er forkert at holde fugle i et bur","Det nye er meget bedre end det gamle","Det ægte er mere værd end det kunstige"],"a":"Det ægte er mere værd end det kunstige","r":"Den grå nattergal ser ikke ud af meget, men dens sang er levende. Den kunstige fugl er flot, men uden liv."},
{"l":4067,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mangler: 'Det er en ___ for at dykke, at man kan svømme.'","o":["forudsætning","forventning","forklaring","fornøjelse"],"a":"forudsætning","r":"En forudsætning er noget, der skal være på plads, før noget andet kan lade sig gøre. Her er svømning et krav."},
{"l":4082,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en skov har stor 'biodiversitet'?","o":["Der står mange meget høje træer","Der lever mange forskellige arter","Der falder meget regn året rundt","Der kommer mange besøgende om året"],"a":"Der lever mange forskellige arter","r":"Bio betyder liv, og diversitet betyder variation. Jo flere forskellige arter, jo større biodiversitet."},
{"l":4104,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bilerne i Havnegade kører for stærkt, skriver en gruppe forældre til kommunen. De har selv målt farten med hjælp fra politiet: 2 ud af 3 biler kørte over 50. Forældrene ønsker et vejbump. Kommunen svarer, at sagen først bliver behandlet efter nytår.' Hvad er forældrenes bedste argument?","o":["De synes, at bilerne er for store til gaden","De ønsker, at kommunen svarer dem hurtigt","De har tal, der viser, at folk kører for stærkt","De ønsker et vejbump i Havnegade"],"a":"De har tal, der viser, at folk kører for stærkt","r":"Tal, de selv har målt, er svære at sige imod. Det gør deres krav stærkere end en løs påstand."},
{"l":4125,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at stjæle' passer: 'Cyklen blev ___ i sidste uge.'","o":["stjal","stjæler","stjæle","stjålet"],"a":"stjålet","r":"Efter 'blev' står den korte tillægsform, og den hedder 'stjålet'. 'Stjal' er datid."},
{"l":4147,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at hjælpe': 'Min bror ___ mig med lektierne i går aftes.'","o":["hjalp","hjulpet","hjælper","hjælpe"],"a":"hjalp","r":"'At hjælpe' bøjes hjælper, hjalp, har hjulpet. 'I går aftes' kræver datid."},
{"l":4165,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder en rangorden, hvor nogle står øverst og andre nederst?","o":["anarki","hierarki","monarki","demokrati"],"a":"hierarki","r":"I et hierarki er nogen over og under hinanden. I middelalderen stod kongen øverst og bønderne nederst. Anarki er derimod, at ingen styrer."},
{"l":4185,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad er en biografi?","o":["En opdigtet fortælling om en persons liv","En bog med fakta om dyr og planter","En bog om et virkeligt menneskes liv","En samling af korte historier"],"a":"En bog om et virkeligt menneskes liv","r":"En biografi fortæller om et menneske, der har levet eller lever. Ordet kommer af græsk og betyder cirka 'livsbeskrivelse'."},
{"l":4202,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning om fuglen har intet genstandsled?","o":["Fuglen bygger en rede.","Fuglen spiser orme.","Fuglen fanger en flue.","Fuglen synger på taget."],"a":"Fuglen synger på taget.","r":"'På taget' siger, hvor fuglen synger, og er et forholdsordsled. I de andre sætninger går handlingen ud over noget."},
{"l":4224,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er den rigtige form? 'Der var mere end tre tusind ___ til håndboldkampen.'","o":["tilskuere","tilskuer","tilskuerer","tilskure"],"a":"tilskuere","r":"Der er mange personer, så navneordet står i flertal og ender på -ere."},
{"l":4240,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Mormor siger, at du skal tage rygtet 'med et gran salt'. Hvad mener hun?","o":["Du skal fortælle det til alle","Du skal ikke tro helt på det","Du skal bruge mere krydderi i maden","Du skal glemme det så hurtigt som muligt"],"a":"Du skal ikke tro helt på det","r":"Et gran er en lille smule. Tager man noget med et gran salt, lytter man, men man er forsigtig med at tro på det."},
{"l":4262,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sara 'tog rygtet for gode varer'. Hvad gjorde hun?","o":["Hun fortalte det videre for at gøre skade","Hun undersøgte det og fandt ud af sandheden","Hun troede på det uden at undersøge det","Hun købte noget billigt i den lokale butik"],"a":"Hun troede på det uden at undersøge det","r":"At tage noget for gode varer er at acceptere det, som det bliver sagt, uden at spørge kritisk ind til det."},
{"l":4286,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Min morfar er en ___ gæst på biblioteket.'","o":["hypig","hyppi","hyppik","hyppig"],"a":"hyppig","r":"Ordet betyder, at noget sker tit. Y'et er kort, så p'et er dobbelt, og ordet ender på -ig."},
{"l":4303,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ordet 'råd' har flere betydninger. Hvad betyder det i 'Hun fik et godt råd af sin moster'?","o":["en idé til, hvad man kan gøre","en gruppe, der træffer beslutninger","penge nok til at købe noget","en svamp, der ødelægger træ"],"a":"en idé til, hvad man kan gøre","r":"Sætningen handler om noget, mosteren siger. Et råd er her en anbefaling, ikke et elevråd eller 'at have råd til noget'."},
{"l":4322,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Er det ___ at tage jakke på i dag?'","o":["nødvenligt","nødvendigt","nøvendigt","nødvendit"],"a":"nødvendigt","r":"Ordet kommer af tysk 'notwendig'. Del det op, når du staver: nød-ven-digt. Der er to d'er, og -t kommer med, fordi ordet hører til 'det'."},
{"l":4344,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'for' i sætningen: 'Kjolen er for lang til mig.'","o":["bindeord","navneord","biord","udsagnsord"],"a":"biord","r":"'For' betyder her 'alt for' og siger noget om tillægsordet 'lang'. Det er et biord."},
{"l":4366,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad sker der med selve ærten til sidst i 'Prinsessen på ærten'?","o":["Den bliver plantet i slotshaven","Den bliver spist af prinsessen","Den bliver smidt ud af dronningen","Den kommer på kunstkammeret"],"a":"Den kommer på kunstkammeret","r":"Eventyret slutter med, at ærten kommer på kunstkammeret, altså en slags museum. Andersen skriver for sjov, at den stadig kan ses, hvis ingen har taget den."},
{"l":4385,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning viser direkte tale rigtigt, når Sofies navn kommer før det, hun siger?","o":["Sofie råbte: »Vent på mig!«","Sofie råbte, »Vent på mig!«","Sofie: råbte »Vent på mig!«","Sofie råbte: Vent på mig!«"],"a":"Sofie råbte: »Vent på mig!«","r":"Der står kolon før den direkte tale, og anførselstegnene omslutter kun det, Sofie siger."},
{"l":4400,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sidste gang Aisha trådte ud på scenen, gik det galt. Hun havde glemt hele teksten. Nu stod hun igen bag tæppet. Hun lukkede øjnene og så for sig, at salen var tom. Da hun åbnede dem, tog hun et skridt frem, og den første linje kom af sig selv.' Hvad gjorde Aisha for at klare det?","o":["Hun bad en anden sige teksten for sig","Hun forestillede sig, at ingen så på","Hun øvede teksten en sidste gang bag tæppet","Hun gik ud af salen og kom igen senere"],"a":"Hun forestillede sig, at ingen så på","r":"Hun ser salen tom for sig. Den forestilling beroliger hende, så hun tør gå frem."},
{"l":4421,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"'Ofte' er et biord i sætningen 'Vi cykler ofte til stranden.' Hvad hedder ordklassen på latin?","o":["adjektiv","substantiv","adverbium","pronomen"],"a":"adverbium","r":"Adverbium betyder biord. Pas på ikke at forveksle det med adjektiv, som er tillægsord."},
{"l":4442,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har kommaet på et rigtigt sted, når Emil fortæller, hvorfor han bliver hjemme?","o":["Fordi jeg, er syg bliver jeg hjemme.","Fordi jeg er syg bliver, jeg hjemme.","Fordi, jeg er syg bliver jeg hjemme.","Fordi jeg er syg, bliver jeg hjemme."],"a":"Fordi jeg er syg, bliver jeg hjemme.","r":"Ledsætningen 'Fordi jeg er syg' står først og slutter efter 'syg'. Derfor skal kommaet stå dér, lige foran 'bliver'."},
{"l":4461,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Bogen tilhører Mette. Hvordan skriver du det rigtigt?","o":["Mettes bog","Mette's bog","Mettes' bog","Mette-s bog"],"a":"Mettes bog","r":"På dansk får ejefald bare et s uden apostrof. Apostrof foran s er en engelsk skrivemåde."},
{"l":4480,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vaskemaskinen og støvsugeren kom ind i hjemmene i 1900-tallet. Før havde arbejdet med tøj og gulve taget mange timer. Man skulle tro, at folk fik meget mere fritid. Men historikere peger på, at man samtidig begyndte at vaske oftere, fordi det var blevet lettere. Tiden forsvandt altså ikke helt.' Hvad er tekstens overraskende pointe?","o":["At maskinerne kun gjorde tingene sværere end før","At folk vaskede mere, fordi det var blevet nemt","At man holdt op med at vaske i hånden","At folk fik meget mere fritid med maskinerne"],"a":"At folk vaskede mere, fordi det var blevet nemt","r":"Man skulle tro, at maskinerne gav fritid, men det nemme arbejde fik folk til at gøre det oftere."},
{"l":4500,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mads fortalte Emil, at han havde vundet lodtrækningen.' Hvilket ord gør sætningen tvetydig?","o":["fortalte","vundet","han","lodtrækningen"],"a":"han","r":"Ordet 'han' kan pege på både Mads og Emil, så man kan ikke vide, hvem der vandt. Det kaldes en uklar henvisning."},
{"l":4520,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvordan er en person, der er 'tolerant'?","o":["altid helt enig med dem, man taler med","rigtig god til at vinde en diskussion med andre","bange for at sige sin egen mening højt i en gruppe","god til at acceptere, at andre tænker anderledes"],"a":"god til at acceptere, at andre tænker anderledes","r":"Man behøver ikke at være enig for at være tolerant. Man lader bare andre mene og leve, som de vil."},
{"l":4538,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Flere kendte ___ udstiller deres malerier på museet.'","o":["kunstnere","kunstner","kunsnere","kunstnerer"],"a":"kunstnere","r":"'Flere' viser, at det er flertal, så ordet ender på -ere. Husk t'et fra 'kunst'."},
{"l":4558,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Den, der ler sidst, ler bedst.' Hvilken form for tekst er det?","o":["gåde","ordsprog","remse","haiku"],"a":"ordsprog","r":"Et ordsprog er en fast, kort sætning med en livsvisdom. Her er visdommen, at man ikke skal glæde sig for tidligt."},
{"l":4580,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad er en limerick?","o":["Et langt, alvorligt digt om krig","En kort fortælling med dyr og moral","Et kort, sjovt digt på fem linjer","En sang, der bliver sunget i kor"],"a":"Et kort, sjovt digt på fem linjer","r":"En limerick er et lille digt på fem linjer, som tit er fjollet. Linje 1, 2 og 5 rimer på hinanden."},
{"l":4598,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'På et ___ kan du se, hvor de store byer i Danmark ligger.'","o":["landskort","lankort","landkårt","landkort"],"a":"landkort","r":"Her er der ikke noget fuge-s mellem de to dele. D'et skal skrives, selvom det er stumt."},
{"l":4613,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Emil og Maja mødte en Svensker i Malmø.'?","o":["Svensker","Malmø","Emil","Maja"],"a":"Svensker","r":"Ord for folk fra et land skrives med lille: en svensker. Personnavne og bynavne får stort."},
{"l":4634,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Vi spiller badminton i byens nye ___.'","o":["idræthal","idrætshal","idrætshall","idrætsal"],"a":"idrætshal","r":"Ordet har fuge-s mellem 'idræt' og 'hal'. 'Hal' staves med ét l."},
{"l":4652,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilket land kommer tegneserien om bjørnen Rasmus Klump fra?","o":["Norge","Sverige","Danmark","Finland"],"a":"Danmark","r":"Rasmus Klump er skabt af danskerne Carla og Vilhelm Hansen. Han tager på eventyr med vennerne Pingo, Pelle og Skæg."},
{"l":4674,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'ude' i sætningen: 'Børnene er ude i gården.'","o":["forholdsord","tillægsord","udsagnsord","biord"],"a":"biord","r":"'Ude' fortæller, hvor børnene er, og er et biord. Forholdsordet i sætningen er 'i'."},
{"l":4694,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Virksomheden vil gerne forbedre sit 'image'. Hvad er det?","o":["det billede, andre har af virksomheden","den pris, virksomheden tager for sine varer","det antal ansatte, virksomheden har","den adresse, virksomheden ligger på"],"a":"det billede, andre har af virksomheden","r":"Image er det indtryk, folk har af en person eller en virksomhed. Ordet er lånt fra engelsk og betyder billede."},
{"l":4707,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken tid står sætningen i: 'Vi vil rejse til Bornholm næste sommer.'","o":["førfremtid","fremtid","datid","førnutid"],"a":"fremtid","r":"'Vil' sammen med en navneform og 'næste sommer' viser, at det endnu ikke er sket."},
{"l":4727,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på stregen: 'Du skal have tre ting med ___ madpakke, regntøj og drikkedunk.'?","o":["apostrof","bindestreg","kolon","semikolon"],"a":"kolon","r":"Kolon varsler, at nu kommer det, der er lagt op til, her en liste over de tre ting."},
{"l":4747,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'overenskomst' på arbejdsmarkedet?","o":["en liste over virksomhedens kunder","en plan over firmaets nye lokaler","en lov om, hvor mange der må ansættes","en aftale om løn og arbejdsforhold"],"a":"en aftale om løn og arbejdsforhold","r":"I Danmark aftaler fagforeninger og arbejdsgivere selv løn og vilkår i overenskomster."},
{"l":4766,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Blyanten er ___ midt over.'","o":["knækket","knæket","knækkede","knækked"],"a":"knækket","r":"K'et er dobbelt, fordi æ'et er kort. Efter 'er' ender ordet her på -et."},
{"l":4785,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'De fleste bier stikker kun, hvis de føler sig truet, og almindelige honningbier dør, efter de har stukket. Stikket sidder fast i huden, og bien mister en del af kroppen. Derfor er det ikke et våben, den bruger let.' Hvad er forfatterens hensigt?","o":["At få læseren til at frygte bier mere end hidtil","At forklare, hvorfor bier ikke stikker uden grund","At vise, hvordan man fjerner et stik fra huden","At forklare, hvorfor bier er farlige for mennesker"],"a":"At forklare, hvorfor bier ikke stikker uden grund","r":"Teksten forklarer bistikket ud fra, hvad det koster bien. Det gør det forståeligt, at den sjældent stikker."},
{"l":4803,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om jakken har de rigtige kommaer omkring den indskudte ledsætning?","o":["Jakken, som ligger på stolen er min.","Jakken som ligger, på stolen er min.","Jakken, som ligger på stolen, er min.","Jakken, som ligger, på stolen er min."],"a":"Jakken, som ligger på stolen, er min.","r":"Ledsætningen 'som ligger på stolen' slutter efter 'stolen', og der skal altid komma efter en ledsætning."},
{"l":4822,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Kun én af sætningerne har en fejl i ejefaldet. Hvilken?","o":["Jeg låner Oskars blyant.","Jeg låner Annas blyant.","Jeg låner Jens' blyant.","Jeg låner Oskar's blyant."],"a":"Jeg låner Oskar's blyant.","r":"Oskar ender ikke på s, så ejefaldet skrives uden apostrof: Oskars. Kun navne på s, x og z får apostrof."},
{"l":4844,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Detektiven i krimien leder efter tyvens 'motiv'. Hvad betyder ordet her?","o":["grunden til, at tyven gjorde det","det sted, hvor tyven gemte sig","den bil, som tyven flygtede i","det navn, som tyven brugte"],"a":"grunden til, at tyven gjorde det","r":"Et motiv er her den grund, der driver nogen til at handle. Ordet kan også betyde det, et billede forestiller."},
{"l":4862,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er rigtigt? 'Katten skal have en lille ___ hos dyrlægen.'","o":["operatjon","operation","operasjon","opperation"],"a":"operation","r":"Ordet har ét p, og endelsen -tion lyder som 'sjon'."},
{"l":4882,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Når politikere taler om 'velfærd', hvad handler det så om?","o":["at landet vinder flest medaljer ved store stævner","at alle mennesker skal blive boende i deres by","at borgerne har det godt og kan få hjælp","at vejene bliver bygget hurtigt og billigt"],"a":"at borgerne har det godt og kan få hjælp","r":"Velfærd betegner et godt liv, og i samfundet handler det om skoler, sundhed og hjælp til dem, der har brug for det."},
{"l":4900,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'De fleste tror, at guldfisk har en hukommelse på tre sekunder. Forsøg viser dog, at de kan lære at finde mad bag en bestemt farve og huske det i ugevis.' Hvad vil teksten især?","o":["Overtale læseren til at købe sig en guldfisk","Vise, at guldfisk er klogere end hunde","Forklare, hvorfor guldfisk er farverige","Fortælle, at mange tager fejl om guldfisk"],"a":"Fortælle, at mange tager fejl om guldfisk","r":"Først står der, hvad de fleste tror, og så viser teksten, at det er forkert. Andre dyr bliver slet ikke nævnt."},
{"l":4920,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad forstår man ved 'selvironi'?","o":["evnen til at gøre lidt grin med sig selv","evnen til at stole på sine egne kræfter","lysten til at tale meget om sig selv","modet til selv at sige sin mening"],"a":"evnen til at gøre lidt grin med sig selv","r":"Med selvironi tager man ikke sig selv alt for højtideligt, men kan smile af sine egne fejl."},
{"l":4938,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Sebastian synes, at Clara altid hilser på ___.'","o":["sig","ham","han","hans"],"a":"ham","r":"'Sig' ville pege på Clara, som er grundled i ledsætningen, og hun hilser ikke på sig selv. Hun hilser på Sebastian, så der skal stå 'ham'."},
{"l":4960,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Naboerne sagde, at ___ ville passe hunden.'","o":["dem","deres","de","sig"],"a":"de","r":"Spørg: Hvem ville passe hunden? Det ville naboerne, og når de selv gør noget, hedder det 'de'. 'Dem' bruger man, når der sker noget med dem."},
{"l":4982,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Krukken på hylden er lavet af ___.'","o":["keramikk","kæramik","kerammik","keramik"],"a":"keramik","r":"Ordet staves med e efter k og ét m. Det ender på -ik."},
{"l":5000,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hanne laver altid sine lektier ved køkkenbordet. I dag ligger hendes bøger på sofaen, og det er ikke, fordi mor har ryddet op.' Hvad er underforstået?","o":["At Hanne selv har flyttet bøgerne","At mor har været sur over rodet","At køkkenbordet er blevet for lille","At Hanne er holdt op med at lave lektier"],"a":"At Hanne selv har flyttet bøgerne","r":"Når det ikke er mor, der har flyttet bøgerne, må det være Hanne selv. Det står ikke direkte, men man kan regne det ud."},
{"l":5012,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Havet er blevet et lager for plast. Plast nedbrydes næsten ikke, men bliver knust til mindre og mindre stykker. Mikroplast er fundet i fisk, i muslinger og i is ved Nordpolen. Vi ved endnu ikke præcis, hvilken betydning det har for mennesker. Men det er næppe noget, vi kan vælge at overse.' Hvad er forfatterens holdning?","o":["At plast er farligere end alle andre stoffer i hele verden","At vi skal tage det alvorligt, selvom vi ikke kender alle svar","At mikroplast ikke betyder noget, før vi ved mere om det","At fisk og muslinger ikke længere bør spises af nogen"],"a":"At vi skal tage det alvorligt, selvom vi ikke kender alle svar","r":"Sætningen 'næppe noget, vi kan vælge at overse' viser forfatterens holdning trods usikkerheden."},
{"l":5032,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det gamle fyrtårn på Sandø står på en klint, som havet tager lidt af hvert år. Hvis intet sker, vælter det inden for få år. En gruppe frivillige vil flytte tårnet 50 meter ind i landet på skinner. Tiden er knap, for efterårets storme kan tage resten af kanten.' Hvad står på spil?","o":["Om de frivillige kan bygge et nyt fyrtårn","Om Sandø kan få mange flere turister til efteråret","Om fyrtårnet kan blive reddet, før det vælter","Om skinnerne kan holde til efterårets storme"],"a":"Om fyrtårnet kan blive reddet, før det vælter","r":"Havet tager klinten, og tårnet vælter, hvis det ikke bliver flyttet. Det er det, de frivillige kæmper for at nå."},
{"l":5054,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Du får en ny ___ i næste runde.'","o":["sjance","chanse","change","chance"],"a":"chance","r":"Ordet er fransk: sj-lyden skrives ch, og ordet ender på -ance."},
{"l":5072,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lars havde cyklet samme rute til arbejde i 20 år. Han kendte hvert hul i vejen. En dag kørte han en anden vej, fordi der var vejarbejde. Han så huse, han aldrig havde set, og en lille kirke med en have. Hvor meget mere var han mon cyklet forbi uden at se det?' Hvad får vejarbejdet Lars til at indse?","o":["At han har overset meget, fordi han altid kører samme vej","At han har kørt den forkerte vej til arbejde i 20 år","At vejene er blevet dårligere de sidste 20 år","At han burde flytte tæt på den lille kirke"],"a":"At han har overset meget, fordi han altid kører samme vej","r":"Efter 20 år på samme rute opdager han noget nyt og spørger sig selv, hvad han ellers er cyklet forbi uden at se det."},
{"l":5092,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hedebranden i år har kostet mange dyr livet. Men om nogle år vil heden se anderledes ud. Lyngen spirer hurtigt igen, og nogle plantearter har faktisk brug for ild, for at deres frø kan spire. For heden kan brand på den måde være både ødelæggelse og begyndelse.' Hvad er tekstens syn på branden?","o":["At den kun har haft dårlige følger for heden","At den både har dårlige og gode virkninger","At heden var bedre, før der kom ild i den","At lyngen aldrig vokser igen efter en brand"],"a":"At den både har dårlige og gode virkninger","r":"Teksten nævner både dyrenes død og nyvæksten. Sætningen med 'både ødelæggelse og begyndelse' samler det."},
{"l":5114,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Efter gymnasiet vil min bror læse på et ___.'","o":["univesitet","universitæt","universitet","univercitet"],"a":"universitet","r":"Ordet ender på -itet med e, og der er r foran s."},
{"l":5132,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sidste år stemte elevrådet for at bruge pengene på en kaffebar til 9. klasse. Efter tre måneder stod den tom. Eleverne foretrak at sidde i gården. Så besluttede rådet at spørge alle elever, før næste beslutning blev taget. Sådan kan en fejl betale sig.' Hvordan kan fejlen betale sig?","o":["Kaffebaren gav et stort overskud til skolen","Kaffebaren kan nu bruges af alle elever","Eleverne har fået lov at sidde i gården","Elevrådet har lært at høre eleverne først"],"a":"Elevrådet har lært at høre eleverne først","r":"Fejlen gav en ny fremgangsmåde: Nu spørger man alle, før man beslutter noget."},
{"l":5150,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Det er svært at ___ sig, når der er larm.'","o":["koncentrere","koncentrerer","konsentrere","koncentreret"],"a":"koncentrere","r":"Efter 'at' står navnemåden på -ere. S-lyden skrives med c."},
{"l":5174,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er forskellen på en sammenligning og en metafor?","o":["En metafor bruger ord som 'som', det gør en sammenligning ikke","En sammenligning bruger ord som 'som', det gør en metafor ikke","En sammenligning er altid på rim, det er en metafor ikke","En metafor handler kun om dyr, det gør en sammenligning ikke"],"a":"En sammenligning bruger ord som 'som', det gør en metafor ikke","r":"'Han er stærk som en bjørn' er en sammenligning. 'Han er en bjørn' er en metafor, for her sættes tingene direkte lig med hinanden."},
{"l":5190,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer? 'Beskyldningerne var ___, for der fandtes ingen beviser.'","o":["berettigede","velkendte","grundløse","tidligere"],"a":"grundløse","r":"Noget grundløst mangler en begrundelse. Uden beviser har beskyldningerne ikke noget at bygge på."},
{"l":5212,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find præpositionsleddet: 'Sneen smelter i solen.'","o":["Sneen","smelter","Sneen smelter","i solen"],"a":"i solen","r":"Præposition er det latinske navn for forholdsord, så et præpositionsled er et forholdsordsled. Det begynder her med præpositionen 'i'."},
{"l":5234,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'I natur og teknologi ___ vi med magneter i denne uge.'","o":["eksperimenterer","eksperimentere","eksprimenterer","eksperimenteret"],"a":"eksperimenterer","r":"Ordet begynder med eks og har e efter p. Nutid ender på -erer."},
{"l":5250,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder forstavelsen 'anti-' i ord som 'antistof' og 'antibiotika'?","o":["før","imod","mange","alene"],"a":"imod","r":"'Anti-' er græsk og betyder imod. Et antistof bekæmper for eksempel fremmede stoffer i kroppen."},
{"l":5270,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Noah vil gerne med til fodboldkamp, men han har lovet at passe sin lillesøster.' Hvilken konflikt står han i?","o":["Han skal vælge mellem to fodboldhold","Hans lillesøster vil også gerne med til kampen","Han kan ikke både gå til kamp og passe sin søster","Han har glemt, hvornår fodboldkampen er"],"a":"Han kan ikke både gå til kamp og passe sin søster","r":"Noah har lyst til at gå til kamp, men han har også lovet noget. En historie bliver tit spændende, når nogen må vælge sådan."},
{"l":5294,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"En forfatter genfortæller 'Rødhætte', så ulven selv siger 'jeg'. Hvad ændrer det mest?","o":["Vi får at vide, hvem der skrev eventyret","Handlingen foregår nu i en anden by","Eventyret bliver til faglitteratur","Vi oplever historien med ulvens øjne"],"a":"Vi oplever historien med ulvens øjne","r":"Når fortælleren skifter, skifter synsvinklen. Læseren får ulvens tanker og ser måske hele historien anderledes."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nogle vil sige, at jeg er for ung til at mene noget om trafikken ved skolen. Men det er mig, der krydser vejen hver morgen.' Hvad bruger skribenten som grund til at mene noget om trafikken?","o":["At skribenten selv krydser vejen hver morgen","At skribenten er gammel nok til at mene noget","At skribenten kender alle trafikreglerne","At skribenten ved, hvad kommunen har planer om"],"a":"At skribenten selv krydser vejen hver morgen","r":"Skribenten svarer ikke på det med alderen, men peger på det, der sker hver morgen. Det er skribenten selv, der krydser vejen."},
{"l":5318,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kalder man det, når vi ser historien gennem en bestemt persons øjne?","o":["miljø","synsvinkel","tema","genre"],"a":"synsvinkel","r":"Synsvinklen afgør, hvis øjne vi ser begivenhederne med. Samme hændelse kan se helt forskellig ud fra to personer."},
{"l":5340,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren streger 'pæn som en prinsesse' over og kalder det en 'kliché'. Hvad er det?","o":["et helt nyt og overraskende sprogligt billede","et ord, der er lånt fra et fremmed sprog","et udtryk, der er brugt så tit, at det er slidt","en sætning, der er grammatisk forkert"],"a":"et udtryk, der er brugt så tit, at det er slidt","r":"En kliché er et slidt udtryk. Den virker ikke længere frisk, fordi den er brugt så mange gange."},
{"l":5356,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvis du får en mail fra din bank, der beder dig skrive din kode, så skal du ikke svare. Banker spørger aldrig om koder i en mail. Svindlere kan lave beskeder, der ligner de ægte, og de skriver tit, at sagen haster. Hastværket skal få dig til at glemme at tænke dig om.' Hvorfor skriver svindlere, at sagen haster?","o":["Fordi banken har brug for koden med det samme","Fordi koden snart holder op med at virke","Fordi banken ellers lukker modtagerens konto","Fordi modtageren så ikke når at tænke sig om"],"a":"Fordi modtageren så ikke når at tænke sig om","r":"Teksten forklarer, at hastværket skal få modtageren til at reagere uden at tænke."},
{"l":5377,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at plukke': 'De ___ blomster stod i en vase.'","o":["plukkede","plukket","plukker","plukke"],"a":"plukkede","r":"Foran et navneord i flertal får tillægsformen endelsen -e, så 'plukket' bliver til 'plukkede'."},
{"l":5399,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken tid står sætningen i: 'Vi vil have spist, inden du kommer.'","o":["fremtid","førfremtid","førnutid","førdatid"],"a":"førfremtid","r":"'Vil have' plus tillægsform viser noget, der vil være overstået på et tidspunkt i fremtiden."},
{"l":5414,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan skrives vendingen? 'Kun én elev må gå ind til lægen ___.'","o":["af gangen","at gangen","ad gangen","a gangen"],"a":"ad gangen","r":"Vendingen skrives med 'ad', altså med d, selvom det lyder som 'a'. Den betyder 'pr. gang'."},
{"l":5435,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad får den lille havfrue og hendes søstre lov til, når de fylder 15 år?","o":["De må besøge havheksen, når de har lyst","De må få hver sin have på havets bund","De må gifte sig med en prins fra land","De må svømme op og se verden over havet"],"a":"De må svømme op og se verden over havet","r":"Havkongens døtre må først svømme op til overfladen, når de fylder 15 år. Den lille havfrue er den yngste, så hun skal vente længst."},
{"l":5454,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form har udsagnsordet 'lukkes' i: 'Butikken lukkes klokken seks.'","o":["passiv","aktiv","bydemåde","lang tillægsform"],"a":"passiv","r":"Endelsen -s kan danne passiv. Butikken bliver lukket, den gør ikke selv noget."},
{"l":5476,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad foregår 'bag kulisserne' i en sag?","o":["det, der sker foran alle","det, der sker i det skjulte","det, der sker bagefter","det, der sker ved en fejl"],"a":"det, der sker i det skjulte","r":"Kulisser er teatrets dekorationer. Bag dem sker det, som publikum ikke kan se."},
{"l":5498,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'sælge skindet, før bjørnen er skudt'?","o":["at forlange alt for meget for en vare","at give op lige før målet er nået","at regne med noget, før det er sikkert","at gøre noget, man ikke har lov til"],"a":"at regne med noget, før det er sikkert","r":"Talemåden advarer mod at tage en gevinst for givet, før man faktisk har den."},
{"l":5512,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'De unge var enige, da de vendte hjem fra Grønland: Det var ikke isen, der gjorde størst indtryk. Det var, at alle hilste på hinanden med navn. I en by på 500 kender alle alle, sagde en af dem. Jeg bor på en vej, hvor jeg ikke kender en eneste nabo.' Hvad var den vigtigste erfaring fra turen?","o":["At isen på Grønland er ved at smelte væk","At isen gjorde størst indtryk på dem alle","At de hellere ville bo i en stor by end i en lille by","At alle i den lille by kendte hinanden, modsat derhjemme"],"a":"At alle i den lille by kendte hinanden, modsat derhjemme","r":"De fortæller selv, at det største var, at alle hilste med navn. Sådan er det ikke på deres egen vej."},
{"l":5532,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvor mange spiser dagligt grønt? Spørger man folk selv, siger de fleste, at de spiser nok. Måler man på indkøb, er tallet meget lavere. Folk svarer ikke nødvendigvis usandt med vilje. Men de fleste mennesker husker sig selv lidt bedre, end de er.' Hvad er forklaringen på forskellen?","o":["Folk husker sig selv lidt bedre, end de er","Folk regner forkert, når de handler ind","Folk ønsker at narre dem, der laver undersøgelsen","Butikkerne fører ikke rigtigt regnskab med grønt"],"a":"Folk husker sig selv lidt bedre, end de er","r":"Sidste sætning giver forklaringen. Teksten siger også, at det ikke er bevidst snyd."},
{"l":5553,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'Hvad du tænker' i sætningen: 'Hvad du tænker, ved jeg ikke.'","o":["grundled","genstandsled","hensynsled","forholdsordsled"],"a":"genstandsled","r":"Grundleddet er 'jeg'. Spørg: Hvad ved jeg ikke? Svaret er ledsætningen, så den er genstandsled, selv om den står først."},
{"l":5573,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'tage afstand' fra en holdning?","o":["at gå nogle skridt tilbage fra den","at måle, hvor langt der er hen til den","at vise, at man ikke er enig i den","at skrive om den i en avis"],"a":"at vise, at man ikke er enig i den","r":"Her er afstand brugt i overført betydning. Man markerer, at man ikke vil have noget med holdningen at gøre."},
{"l":5594,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Læren om jordens sten og lag har et bestemt navn. Hvordan staves det?","o":["jeologi","geoloji","geolugi","geologi"],"a":"geologi","r":"Ordet begynder med g og slutter på -logi ligesom 'biologi'."},
{"l":5611,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'forgængelig'?","o":["noget, der ikke varer ved","noget, der er gået forbi på vejen","noget, der aldrig kan ændre sig","noget, der er meget dyrt"],"a":"noget, der ikke varer ved","r":"Det forgængelige forsvinder før eller siden, ligesom en blomst, der visner."},
{"l":5630,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Kunstneren malede et ___ af dronningen.'","o":["portrætt","portræt","portrait","pårtræt"],"a":"portræt","r":"Ordet staves med æ og slutter på ét t."},
{"l":5652,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Dette er ikke en reklame, skriver influenceren. Hun har bare lyst til at fortælle om den fantastiske creme. Længere nede står der med små grå bogstaver: Samarbejde. Læseren kan så tænke over, hvad der er værst: at hun ikke er ærlig, eller at så mange ikke læser så langt.' Hvad er skribentens holdning til influencerens tekst?","o":["Skribenten beundrer teksten for dens ærlige tone","Skribenten synes, at reklamer bør forbydes","Skribenten kan ikke lide, at reklamen bliver skjult","Skribenten mener, at cremen ikke virker"],"a":"Skribenten kan ikke lide, at reklamen bliver skjult","r":"Influenceren siger, at det ikke er reklame, men 'Samarbejde' afslører det modsatte. Det kritiserer skribenten."},
{"l":5672,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg har en ven, der altid siger, at han er ligeglad. Med karakterer, med venner, med hvem der vinder. Han siger det, så snart nogen spørger. Jeg tror, man skal bruge rigtig mange kræfter på at være så ligeglad. Når han er alene, ser han ud, som om han er træt.' Hvad antyder fortælleren om vennen?","o":["At han faktisk er ligeglad med det hele","At han har brug for mere søvn om natten","At han helst vil have, at folk spørger om noget andet","At det betyder mere for ham, end han vil indrømme"],"a":"At det betyder mere for ham, end han vil indrømme","r":"Det koster kræfter at spille ligeglad, og det kan man se på ham. Det viser, at han faktisk går op i det."},
{"l":5692,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi nåede toppen efter tolv timer. Tågen lå så tæt, at vi ikke kunne se vores egne støvler. Heldigvis havde vi slæbt det tunge kamera med hele vejen.' Hvad betyder ordet 'heldigvis' her?","o":["Det er ironisk, for kameraet er ubrugeligt i den tåge","Det er ærligt ment, for nu kan turen alligevel huskes","Det viser, at kameraet ikke gik i stykker på vejen op","Det viser, at kameraet hjalp dem med at finde vej i tågen"],"a":"Det er ironisk, for kameraet er ubrugeligt i den tåge","r":"Når man ikke kan se sine egne støvler, er der intet at fotografere, så ordet betyder det modsatte af det, det siger. Læst bogstaveligt lyder det ærligt, men det passer ikke med tågen."},
{"l":5716,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'minoritet', når man taler om en befolkning?","o":["en optælling","et mindretal","et flertal","en leder"],"a":"et mindretal","r":"En minoritet er en gruppe, der er færre end resten. Det modsatte ord er majoritet, som betyder flertal."},
{"l":5733,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Bilen kørte langsomt op ___ bakken.'","o":["af","at","ad","og"],"a":"ad","r":"'Op ad' viser, at man bevæger sig langs bakken, og skrives med d. 'Af' bruger man, når noget kommer ud fra noget, for eksempel 'op af vandet'."},
{"l":5750,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hendes øjne var som to blanke søer.' Hvilket sprogligt billede bruger forfatteren?","o":["metafor","personifikation","allitteration","sammenligning"],"a":"sammenligning","r":"Ordet 'som' binder øjnene og søerne sammen, og det gør billedet til en sammenligning. En metafor ville sige, at øjnene ER søer."},
{"l":5771,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vores kantine sælger kun sund mad, og det er godt. Men hvad hjælper det, når prisen er så høj, at halvdelen af os tager madpakke med? Sund mad virker kun, hvis nogen spiser den.' Hvad er skribentens hovedpointe?","o":["Sund skolemad skal også være til at betale","Madpakker er sundere end maden i kantinen","Kantinen bør begynde at sælge usund mad","Halvdelen af eleverne bryder sig ikke om sund mad"],"a":"Sund skolemad skal også være til at betale","r":"Skribenten roser den sunde mad, men kritiserer prisen. Problemet er altså ikke maden, men at for få har råd til at købe den."},
{"l":5793,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Regnorme graver gange i jorden og trækker visne blade ned med sig. Gangene lader luft og vand trænge ned til planternes rødder. Bladene bliver til næring i jorden.' Hvad er tekstens formål?","o":["At få læseren til at passe bedre på regnorme","At forklare, hvordan regnorme gavner jorden","At vise, at regnorme er vigtigere end andre dyr","At fortælle, hvad regnorme lever af"],"a":"At forklare, hvordan regnorme gavner jorden","r":"Teksten forklarer bare, hvad ormene gør godt for jorden. Den beder ikke læseren om at gøre noget, og den sammenligner dem ikke med andre dyr."},
{"l":5811,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Min oldemor blev ___ år, og hele familien kom.'","o":["halfems","halvfemse","halvfems","halvfæms"],"a":"halvfems","r":"Ordet betyder 90. Det skrives med v i 'halv' og e i '-fems'."},
{"l":5828,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Der er tilstrækkelig mad til alle.' Hvilket ord kan stå i stedet for 'tilstrækkelig'?","o":["gratis","varm","sund","nok"],"a":"nok","r":"'Tilstrækkelig' betyder, at mængden rækker. Det er et mere formelt ord end 'nok'."},
{"l":5850,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'I myldretiden er der tæt ___ på motorvejen.'","o":["færdsel","færsel","færdssel","fædsel"],"a":"færdsel","r":"Ordet hænger sammen med 'færd', så det stumme d skal med. Der er kun ét s."},
{"l":5870,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er et verbum i s-form: 'Lars går hjem, når butikken lukkes klokken seks.'?","o":["Lars","lukkes","seks","går"],"a":"lukkes","r":"S-form er et verbum, der ender på -s. 'Lars' og 'seks' ender også på -s, men de er ikke verber. 'Lukkes' viser passiv: Nogen lukker butikken."},
{"l":5889,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Udfyld sætningen: 'Jeg vil ___, at vi holder en kort pause.'","o":["forslå","foreslag","foreslå","forslag"],"a":"foreslå","r":"Udsagnsordet har et e i midten: fore-slå. Navneordet hedder derimod et forslag."},
{"l":5903,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"I hvilken genre foregår handlingen ofte på et ubestemt sted og i en ubestemt tid?","o":["sagn","historisk roman","reportage","eventyr"],"a":"eventyr","r":"Eventyret foregår i en tid og et sted, der ikke kan bestemmes nærmere, og det ender gerne godt for helten."},
{"l":5926,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sara tegner et 'abonnement' på et magasin. Hvad betyder det?","o":["hun betaler fast og får bladet hver gang","hun køber ét enkelt blad i kiosken","hun låner bladet gratis på biblioteket","hun skriver selv artikler til bladet"],"a":"hun betaler fast og får bladet hver gang","r":"Et abonnement er en aftale om at få noget leveret igen og igen mod fast betaling, til man opsiger det."},
{"l":5948,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Tandlægen skriver i en sms: 'Bekræft venligst din tid.' Hvad skal du gøre?","o":["finde en ny tid","svare, at du kommer","aflyse tiden","betale regningen"],"a":"svare, at du kommer","r":"At bekræfte er at sige, at noget passer eller står fast. Tandlægen vil vide, at aftalen holder."},
{"l":5969,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Rasmus fortalte hele klassen, at han ikke var bange for edderkopper. I pausen gik han alligevel en stor bue uden om cykelskuret, hvor spindet hang. Da nogen spurgte hvorfor, sagde han, at han bare godt kunne lide at gå lidt længere.' Hvad kan man regne ud om Rasmus?","o":["Han kan godt lide at gå lidt længere i pausen.","Han går uden om, fordi han ikke vil ødelægge spindet i cykelskuret.","Han er bange for edderkopper, men vil ikke sige det.","Han er ikke bange for edderkopper, sådan som han selv siger."],"a":"Han er bange for edderkopper, men vil ikke sige det.","r":"Rasmus siger, at han ikke er bange, men han går en stor bue uden om spindet. Det, han gør, passer ikke med det, han siger."},
{"l":5991,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er talesprog i sætningen: 'Filmens handling var vildt spændende og usædvanligt velspillet.'?","o":["usædvanligt","handling","velspillet","vildt"],"a":"vildt","r":"'Vildt' bruges i talesprog i stedet for 'meget'. 'Usædvanligt' forstærker også, men det kan godt stå i en formel tekst."},
{"l":6001,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kendetegner 'propaganda'?","o":["ensidig information, der skal påvirke folks holdninger","nøgtern information, der viser alle sider af en sag","en sjov tegning, der gør grin med kendte personer","en kort besked fra myndighederne om vejret"],"a":"ensidig information, der skal påvirke folks holdninger","r":"Propaganda viser kun én side af sagen med vilje. Formålet er ikke at oplyse, men at få modtageren til at mene noget bestemt."},
{"l":6020,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning har en rigtig genitiv af 'Danmark'?","o":["Danmark's hovedstad er København.","Danmarks hovedstad er København.","Danmarks' hovedstad er København.","Danmark-s hovedstad er København."],"a":"Danmarks hovedstad er København.","r":"Genitiv dannes med et s direkte på ordet, uden apostrof."},
{"l":6040,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Polen er et ___.'? Landet er medlem af Den Europæiske Union.","o":["EU land","EUland","EU-land","EU'land"],"a":"EU-land","r":"En forkortelse, der sættes sammen med et ord, bindes til det med bindestreg."},
{"l":6060,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type ledsætning findes i: 'Den hund, der bor ved siden af, larmer hele natten.'?","o":["at-sætning","adverbialsætning","spørgende ledsætning","relativsætning"],"a":"relativsætning","r":"'Der bor ved siden af' siger noget nærmere om navneordet 'hund'. Det er det, en relativsætning gør."},
{"l":6082,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket bindeord indleder en ledsætning: 'Karl og Ida smiler, men Emil sukker, når han får ros.'?","o":["når","og","men","han"],"a":"når","r":"'Når' står først i den del, der ikke kan stå alene: 'når han får ros'. 'Og' og 'men' er også bindeord, men de binder dele sammen, der er lige gode, og indleder ikke en ledsætning."},
{"l":6100,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jorden omkring vulkaner er ofte meget frugtbar. Derfor bor millioner af mennesker tæt på dem, selv om et udbrud kan ødelægge alt.' Hvad vælger folk ifølge teksten?","o":["De bliver, fordi vulkaner næsten aldrig går i udbrud","De bliver for den gode jord, selv om det er farligt","De ved slet ikke, at vulkanerne er farlige","De bor der, fordi der ikke er plads andre steder"],"a":"De bliver for den gode jord, selv om det er farligt","r":"'Selv om' viser, at folk godt ved, at det er farligt. De bliver alligevel, fordi jorden er så god."},
{"l":6115,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type stedord er 'hvem' i: 'Jeg ved ikke, hvem der har taget min lineal.'?","o":["henførende stedord","personligt stedord","spørgende stedord","påpegende stedord"],"a":"spørgende stedord","r":"'Hvem' indleder her et skjult spørgsmål: Hvem har taget linealen? Derfor er det et spørgende stedord, som også kaldes interrogativt, selv om sætningen ikke har spørgsmålstegn."},
{"l":6136,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg den rigtige flertalsform: 'Alle ___ kom til mødet om lejrturen.'","o":["forældrerne","forældrende","forældreene","forældrene"],"a":"forældrene","r":"'Forældre' ender på -e, så bestemt flertal får kun -ne: forældrene. Det er ikke en -ende-form, så der er intet d."},
{"l":6158,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Lugten af fisk rammer mig, da jeg træder ind på havnen klokken fem. En mand i gule gummistøvler nikker søvnigt til mig.' Hvilken journalistisk genre er det?","o":["reportage","leder","anmeldelse","læserbrev"],"a":"reportage","r":"Journalisten tager læseren med til stedet og bruger sine sanser. Det er reportagens kendetegn."},
{"l":6178,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Læserbrev i klubbladet: Cykelstativet ved hallen er et stort problem. Sidste torsdag gik jeg rundt i ti minutter og ledte efter en plads. Klubben må straks købe flere stativer.' Hvad er den største svaghed i læserbrevet?","o":["Skribenten skriver ikke, hvilken torsdag det var","Hele kravet bygger på en enkelt oplevelse","Skribenten skriver ikke, hvad hallen bruges til","Ti minutter er ikke særlig præcist angivet"],"a":"Hele kravet bygger på en enkelt oplevelse","r":"Skribenten har kun ledt efter en plads én torsdag. Det er for lidt at kræve nye stativer på."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Efter to år og tre bestyrelsesmøder er klubbens bedste bud på et nyt klubhus en ny dørmåtte. Men her er vi så.' Hvad er skribentens holdning til dørmåtten?","o":["Det er et flot resultat efter så lang tid","Det var slet ikke nødvendigt at købe den","Det er alt for lidt efter så lang tid","Den fylder alt for meget i gangen"],"a":"Det er alt for lidt efter så lang tid","r":"To år og tre møder endte med en dørmåtte. 'Bedste bud' er ment spydigt: Skribenten synes, at en dørmåtte er alt for lidt."},
{"l":6211,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Hele holdet lagde sig i selen før finalen.' Hvad gjorde holdet?","o":["holdt en lang pause","opgav på forhånd","kørte i bus til stadion","gjorde en stor indsats"],"a":"gjorde en stor indsats","r":"Billedet kommer fra trækheste, der læner sig ind i seletøjet for at trække et tungt læs."},
{"l":6227,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Det var en så ___ bog, at jeg ikke kunne lægge den fra mig.'","o":["spændende","spændene","spænende","spendende"],"a":"spændende","r":"Ordet er dannet af 'spænde' med -ende. 'Spændene' er flertal af 'et spænde', altså noget helt andet."},
{"l":6248,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Ansatte melder sig ind i en 'fagforening'. Hvad er det?","o":["et firma, der finder nye ansatte til virksomheder","en organisation, der arbejder for de ansattes vilkår","et kontor, der udbetaler pension fra staten","en skole, hvor voksne kan lære et nyt fag"],"a":"en organisation, der arbejder for de ansattes vilkår","r":"En fagforening forhandler løn og arbejdsvilkår og hjælper sine medlemmer, hvis der opstår problemer på arbejdet."},
{"l":6271,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Skolen kan optage 20 nye elever.' Hvad betyder 'optage' her?","o":["filme","opsuge","tage imod","afvise"],"a":"tage imod","r":"'Optage' har flere betydninger. Her handler det om at give nogen plads i en skole eller forening."},
{"l":6294,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvorfor rejste den unge H.C. Andersen fra Odense til København i 1819?","o":["For at læse på universitetet","For at blive udlært som skrædder","For at blive soldat i kongens hær","For at komme til teatret"],"a":"For at komme til teatret","r":"Han var 14 år og drømte om at blive skuespiller. Derfor tog han alene til København for at komme til teatret."},
{"l":6301,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I biologi kan der ske en 'mutation'. Hvad er det?","o":["en ændring i et levende væsens gener","en sygdom, der smitter gennem luften","et dyrs skift af pels om vinteren","en plante, der vokser usædvanligt hurtigt"],"a":"en ændring i et levende væsens gener","r":"En mutation er en ændring i DNA'et. Den kan føres videre til afkommet og er en af forudsætningerne for evolution."},
{"l":6323,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find forholdsordsleddet: 'Katten sov under sengen hele dagen.'","o":["Katten","under sengen","sov","hele dagen"],"a":"under sengen","r":"Et forholdsordsled er et forholdsord plus det ord, det hører sammen med: 'under' + 'sengen'. 'Hele dagen' har ikke noget forholdsord."},
{"l":6345,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning har s-passiv i datid?","o":["Slottet bygges om i disse år.","Slottet blev bygget af kongen.","Slottet byggedes i 1600-tallet.","Slottet er bygget af mursten."],"a":"Slottet byggedes i 1600-tallet.","r":"'Byggedes' er datid med -s. 'Bygges' er nutid, og 'blev bygget' og 'er bygget' er passiv dannet med hjælpeverber."},
{"l":6365,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Efter min fremlæggelse så læreren længe på sine noter. Nå, sagde hun så. Det var jo også en måde at gøre det på.' Hvad giver hendes svar indtryk af?","o":["At hun ikke har hørt efter","At hun synes, det var en spændende idé","At hun er helt overvældet","At hun ikke er imponeret"],"a":"At hun ikke er imponeret","r":"Hun siger hverken godt eller dårligt, men 'også en måde' lyder ikke begejstret. Det er en høflig måde at sige, at det ikke var så godt."},
{"l":6387,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mange tror, at mælkebøttens gule hoved er én blomst. I virkeligheden består det af mange små blomster. Hver af dem kan give et frø med sin egen lille faldskærm.' Hvad kan man slutte om mælkebøtten?","o":["Én plante kan sprede mange frø på én gang","Dens frø kan kun spire ved siden af planten","Den har kun ét frø i hvert gult hoved","Den gule farve skal beskytte frøene"],"a":"Én plante kan sprede mange frø på én gang","r":"Mange småblomster giver mange frø, og faldskærmen får dem til at flyve. Det er en slutning, teksten lægger op til."},
{"l":6406,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Efter valget danner man en 'koalitionsregering'. Hvad er det?","o":["en regering af kun ét parti","en regering af flere partier","en regering, der ledes af kongen","en regering, der kun består af embedsmænd"],"a":"en regering af flere partier","r":"En koalition er et samarbejde mellem flere parter. I en koalitionsregering deler partierne ministerposterne."},
{"l":6422,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sætningsled er at-sætningen i: 'Jeg håber, at du får det bedre.'?","o":["grundled","hensynsled","genstandsled","omsagnsled"],"a":"genstandsled","r":"Spørg: Hvad håber jeg? Svaret er hele at-sætningen, så den er genstandsled i hovedsætningen."},
{"l":6444,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken relativsætning har rigtig ordstilling: 'Hun er den eneste, …'?","o":["der kommer altid til tiden","altid der kommer til tiden","kommer der altid til tiden","der altid kommer til tiden"],"a":"der altid kommer til tiden","r":"En relativsætning er en ledsætning, så biordet 'altid' skal stå foran verbet."},
{"l":6466,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Vi købte et ___ tæppe til stuen.'?","o":["blødt","bløt","blød","bløde"],"a":"blødt","r":"'Tæppe' er et intetkønsord i ental, så tillægsordet får -t. D'et fra 'blød' bliver stående, selv om man ikke kan høre det."},
{"l":6488,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find det tilbagevisende stedord: 'Hun skyndte sig hjem fra skole.'","o":["Hun","sig","hjem","skole"],"a":"sig","r":"'Sig' viser tilbage til grundleddet 'hun'. Det kaldes også et refleksivt stedord."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'På Emils skolepapir står der: Emil har fine evner, når han vælger at bruge dem.' Hvad siger læreren egentlig?","o":["At Emil har valgt de rigtige fag","At Emil altid bruger sine evner","At Emil ikke altid gør sig umage","At Emil har svært ved det faglige"],"a":"At Emil ikke altid gør sig umage","r":"Rosen rummer en kritik: 'når han vælger' betyder, at han ofte ikke gør det. Det er en høflig måde at sige det på."},
{"l":6519,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ja, papirbøger er tunge at have med på ferie. Ja, en e-bogslæser kan rumme hundredvis af titler. Men en papirbog har aldrig stået sort og tavs på en strand, fordi strømmen slap op.' Hvad opnår skribenten med de to sætninger, der begynder med 'Ja'?","o":["Skribenten viser begge sider, så læseren selv må vælge","Skribenten indrømmer, at e-bogen alt i alt er det bedste valg","Skribenten peger på papirbogens svage sider for at få læseren til at skifte","Skribenten giver modparten ret først, så det sidste virker stærkere"],"a":"Skribenten giver modparten ret først, så det sidste virker stærkere","r":"Skribenten siger 'Ja' to gange og giver modparten ret. Så lyder det fair, når 'Men' kommer med det stærkeste argument. Slutningen viser, at skribenten holder med papirbogen."},
{"l":6540,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor står der komma i 'Far laver maden, og mor dækker bordet.'?","o":["Fordi begge sætninger har eget grundled","Fordi 'og' altid skal have komma foran","Fordi 'mor' er en tiltale i sætningen","Fordi 'maden' står i bestemt form"],"a":"Fordi begge sætninger har eget grundled","r":"Der er to hovedsætninger med hvert sit grundled, 'far' og 'mor'. Mellem dem skal der komma."},
{"l":6560,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning bruger kolon forkert?","o":["Hun sagde kun ét: Jeg er træt.","Hun sagde: at hun var træt.","Vi har to kæledyr: en kat og en hamster.","Der står på skiltet: Adgang forbudt."],"a":"Hun sagde: at hun var træt.","r":"'at hun var træt' er indirekte tale, og den skal ikke varsles med kolon."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
